import{_ as e,o,c as s,ag as a}from"./chunks/framework.DyZQ0-wY.js";const f=JSON.parse('{"title":"How the bot chooses your feet","description":"","frontmatter":{},"headers":[],"relativePath":"footnotes/footing.md","filePath":"footnotes/footing.md"}'),r={name:"footnotes/footing.md"};function n(h,t,i,l,d,c){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="how-the-bot-chooses-your-feet" tabindex="-1">How the bot chooses your feet <a class="header-anchor" href="#how-the-bot-chooses-your-feet" aria-label="Permalink to &quot;How the bot chooses your feet&quot;">​</a></h1><p>The dancing bot doesn&#39;t decide one step at a time. When a chart loads, Footnotes looks at the whole chart and chooses a foot for every arrow, picking the combination that&#39;s easiest to dance from start to finish. Rhythm games call this the chart&#39;s parity, and Footnotes works it out with SMEditor&#39;s <a href="./../parity.html">parity checker</a> and the rules below.</p><h2 id="the-rules" tabindex="-1">The rules <a class="header-anchor" href="#the-rules" aria-label="Permalink to &quot;The rules&quot;">​</a></h2><ol><li><strong>One foot per arrow, two for a jump.</strong> Each arrow is stepped by one foot. When two arrows come at the same time, that&#39;s a jump, and both feet land together.</li><li><strong>Two feet never share an arrow.</strong> If one foot is standing on an arrow, putting the other foot on it doesn&#39;t press it again. So when the same arrow comes twice in a row, the foot that&#39;s already on it steps it again.</li><li><strong>Alternate when it&#39;s comfortable.</strong> Left, right, left, right is the default, as long as each foot can stay on its own side of the pad.</li><li><strong>The same foot twice is fine when it&#39;s slow.</strong> When steps are 0.4 seconds or more apart, the bot would rather step twice with the same foot than cross your legs over.</li><li><strong>Fast passages alternate.</strong> When steps are 0.2 seconds apart or closer, stepping twice with one foot is hard, so the bot alternates, crossing over or turning your body when the chart needs it.</li><li><strong>Small moves, facing the screen.</strong> The bot prefers short moves between arrows, and avoids turning your back to the screen.</li><li><strong>Holds keep a foot in place.</strong> A foot holding an arrow stays on it until the hold ends, and the other foot takes the other arrows.</li><li><strong>Brackets.</strong> Sometimes one foot presses two arrows next to each other at once, with the heel on one and the toes on the other.</li></ol><h2 id="how-fast-is-slow" tabindex="-1">How fast is slow? <a class="header-anchor" href="#how-fast-is-slow" aria-label="Permalink to &quot;How fast is slow?&quot;">​</a></h2><p>What the bot does depends on the time between two steps:</p><table tabindex="0"><thead><tr><th>Time between steps</th><th>What the bot does</th><th>For example</th></tr></thead><tbody><tr><td>0.4 s or more</td><td>Steps twice with the same foot rather than crossing over</td><td>Quarter notes up to 150 BPM, eighth notes up to 75 BPM</td></tr><tr><td>0.2 s to 0.4 s</td><td>Weighs both, leaning more toward alternating as it speeds up</td><td>Quarter notes from 150 to 300 BPM, eighth notes from 75 to 150 BPM</td></tr><tr><td>0.2 s or less</td><td>Alternates, and crosses over when it has to</td><td>Eighth notes from 150 BPM, sixteenth notes from 75 BPM</td></tr></tbody></table><h2 id="an-example" tabindex="-1">An example <a class="header-anchor" href="#an-example" aria-label="Permalink to &quot;An example&quot;">​</a></h2><p>Take <strong>Left, Down, Right, Down</strong> as quarter notes at 120 BPM, half a second apart. Strictly alternating feet would send your left foot across your right leg to reach the Right arrow. The bot steps Left and Down with the left foot instead, and Right with the right foot, so your legs never cross.</p><p>As eighth notes at 150 BPM, a fifth of a second apart, there&#39;s no time to step twice with one foot, so the bot alternates and crosses over.</p><h2 id="the-footing-setting" tabindex="-1">The Footing setting <a class="header-anchor" href="#the-footing-setting" aria-label="Permalink to &quot;The Footing setting&quot;">​</a></h2><p>The chart editor&#39;s <strong>Preferences &gt; Parity &gt; Footing</strong> setting chooses between two sets of rules:</p><ul><li><strong>Natural</strong> (the default) uses the rules above.</li><li><strong>Alternating</strong> is SMEditor&#39;s original footing. It alternates feet whenever it can, crossing over, or switching feet on an arrow, to avoid stepping twice with the same foot, even in slow passages.</li></ul><p>To get to Preferences while practicing, press <strong>Exit practice</strong> first.</p><h2 id="when-the-footing-looks-wrong" tabindex="-1">When the footing looks wrong <a class="header-anchor" href="#when-the-footing-looks-wrong" aria-label="Permalink to &quot;When the footing looks wrong&quot;">​</a></h2><p>The bot&#39;s footing is a suggestion. Many patterns can be danced more than one way, and the bot shows one of them. If you&#39;d dance a step with the other foot, trust your body. To change a step for good, correct it in the chart editor, as described in <a href="./../parity.html#correcting-the-parity-checker">Correcting the parity checker</a>.</p>',16)])])}const w=e(r,[["render",n]]);export{f as __pageData,w as default};
